const stateElement = document.querySelector("#doorState");
const connectionElement = document.querySelector("#connection");
const confirmedAtElement = document.querySelector("#confirmedAt");
const faultElement = document.querySelector("#fault");
const actionButtons = Array.from(document.querySelectorAll("[data-action]"));
let refreshTimer = 0;

const labels = { open: "Offen", closed: "Geschlossen", opening: "Öffnet", closing: "Schließt", stopped: "Gestoppt", blocked: "Blockiert", unknown: "Unbekannt" };

function setButtonsEnabled(enabled) {
  for (const button of actionButtons) button.disabled = !enabled;
}

function enterUnknownState(message) {
  stateElement.textContent = labels.unknown;
  connectionElement.textContent = message;
  confirmedAtElement.textContent = "nicht aktuell";
  faultElement.hidden = true;
  setButtonsEnabled(false);
}

function renderStatus(status) {
  const knownState = Object.hasOwn(labels, status.controller_state) ? status.controller_state : "unknown";
  stateElement.textContent = labels[knownState];
  connectionElement.textContent = "Mit dem Stallcontroller verbunden";
  confirmedAtElement.dateTime = status.last_confirmed_at;
  confirmedAtElement.textContent = new Date(status.last_confirmed_at).toLocaleString();
  faultElement.hidden = !status.fault;
  faultElement.textContent = status.fault ? `Störung: ${status.fault}` : "";
  setButtonsEnabled(knownState !== "unknown");
}

async function refreshStatus() {
  window.clearTimeout(refreshTimer);
  try {
    const response = await fetch("/api/door/status", { cache: "no-store", signal: AbortSignal.timeout(3500) });
    if (!response.ok) throw new Error(`status_${response.status}`);
    renderStatus(await response.json());
  } catch {
    enterUnknownState("Keine aktuelle Rückmeldung – Zustand vor Ort prüfen");
  } finally {
    refreshTimer = window.setTimeout(refreshStatus, 3000);
  }
}

async function requestAction(desiredAction) {
  setButtonsEnabled(false);
  connectionElement.textContent = `${desiredAction} wird angefordert …`;
  try {
    const response = await fetch("/api/door/commands", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ command_id: crypto.randomUUID(), desired_action: desiredAction }),
      signal: AbortSignal.timeout(3500),
    });
    if (!response.ok) throw new Error(`command_${response.status}`);
    const result = await response.json();
    connectionElement.textContent = result.accepted ? "Befehl angenommen – warte auf Controllerzustand" : "Befehl abgelehnt";
    await refreshStatus();
  } catch {
    enterUnknownState("Befehlsausgang unklar – nicht automatisch wiederholen");
  }
}

for (const button of actionButtons) button.addEventListener("click", () => requestAction(button.dataset.action));
if ("serviceWorker" in navigator) navigator.serviceWorker.register("sw.js");
refreshStatus();

const SHELL_CACHE = "chicken-door-shell-v1";
const SHELL_FILES = ["./", "index.html", "app.js", "manifest.webmanifest"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(SHELL_CACHE).then((cache) => cache.addAll(SHELL_FILES)));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(caches.keys().then((keys) => Promise.all(keys.filter((key) => key !== SHELL_CACHE).map((key) => caches.delete(key)))));
});

self.addEventListener("fetch", (event) => {
  const url = new URL(event.request.url);
  if (url.pathname.startsWith("/api/door/")) return;
  if (event.request.method !== "GET") return;
  event.respondWith(fetch(event.request).catch(() => caches.match(event.request).then((response) => response || caches.match("index.html"))));
});
